/* Project NEO · S/4HANA verification overlay · transactions, shard E.
   ----------------------------------------------------------------------------
   Same contract as the other transaction shards (VerificationRecord[], see
   lib/evidence/types.ts). Opened on 2026-09-25 so the named-code queue can run as
   four parallel research chains, one writer per file.
   data/verification/index.ts merges all shards and throws on a duplicate id.
   Open repository conflicts live in audit/s4-enrichment/research-queue-transactions-e.md.
   Batch 1 (research + adversarial audit 2026-09-25, written 2026-09-28, access
   date stamped 2026-09-25): 8 audited records for the PS simulation,
   workforce-planning, project-text and network codes (CJV4, CJV5, CJV6, CMP9,
   CN04, CN05, CN19, CN21); none refuted. CJV4, CJV5 and CJV6 are 'changed'
   from the item 'S4TWL - Current simulation functions in project system'
   (perpetual scope after the 2020 FPS2 field-extensibility enhancement); CN19
   and CN21 are 'changed' from 'S4TWL - Simplification of maintenance
   transactions' (CN21 also cites 'S4TWL - Production Resources and Tools
   functions for projects', which names it only as a PRT indicator); CN04 and
   CN05 are 'compatibility_scope' from 'S4TWL - Project texts (PS texts)', with
   no successor because no cited record prints a Fiori app id for 'Project
   Text'; CMP9 stays verification_required, because 'S4TWL - Workforce Planning'
   lists it under the compatibility scope and says workforce planning is
   perpetual scope from 2023 without saying whether that covers CMP9. Seven
   taken from verdict.fixedRecord; CMP9 written from the draft (the audit found
   no problem). Every status source is a shared const (the record's own item
   row) instead of the pointer string or the copy the verdicts carried. Writer
   corrections: the empty alias lists dropped (CJV5, CJV6); the CJV6 status.he
   names the item instead of its bare number (HOUSE-RULES §3.5) and keeps its
   compatibility-scope clause inside the item's own wording; the CN19
   repository row no longer calls the catalog's English label official (the
   item prints another label, see the queue file); Old → New lines
   added (CJV4, CJV5, CJV6, CMP9, CN19, CN21); the rows of the generated records
   that the audited records left out carried over verbatim as context rows with
   their 2026-09-24 access date (CJV4: its Fiori Apps Library row; CJV5: both
   'Maintaining and Displaying Project Structures' search records; CMP9: both
   'Evaluating Human Resources' search records; CN04: both 'Maintaining and
   Displaying Documents' search records; CN21: its repository row and the 2023
   FPS03 item 32.12 row, whose 'not yet read' frame sentence was replaced). The
   generated records for the eight ids in transactions-auto.ts are superseded.
   Batch 2 (research and adversarial audit 2026-09-28, written 2026-09-28, access
   date stamped 2026-09-25): 7 audited records for gateway, web-service, Basis and
   inbound-delivery codes (/IWFND/MAINT_SERVICE, DBACOCKPIT, OSS1, SAINT, SRT_MONI,
   SXMB_MONI, VL60); SOAMANAGER refuted and queued. VL60 is 'restricted' from the
   Restriction section of 'Extended Goods Receipt Process' (SAP replaced the process
   with Advanced Shipping and Receiving; no successor code is named); OSS1 is
   'restricted' from 'ABAPTWL - Removal of OSS1 (Logon to SAP Service Marketplace)'
   (the item names no successor, so not_available cannot be written); the other
   five are 'unchanged'. All seven taken from verdict.fixedRecord, each status
   source a shared const (the record's own row). Writer corrections: sapNote
   dropped from the OSS1 and SAINT item rows (sap-note-format needs a
   me.sap.com/notes url or a repoRef; the numbers stay in the text); 'only'
   wording and bare item numbers in status copy reworded (HOUSE-RULES §3.2, §3.5);
   Old → New lines added or corrected (/IWFND/MAINT_SERVICE, SRT_MONI, the VL60
   row count); the writer instruction removed from the SAINT notes; the empty
   SXMB_MONI alias list dropped; the rows of the generated records that the
   audited records left out carried over verbatim as context rows with their
   2026-09-24 access date (item rows with the 'not yet read' frame sentence
   replaced, because the research read those items). The generated records for
   the seven ids in transactions-auto.ts are superseded.
   Batch 3 (research and adversarial audit 2026-09-28, written 2026-09-28, access
   date stamped 2026-09-25): 8 audited records for Basis codes (SICF, SLG1, SM01,
   SM31, SM36, SM37, SNOTE, SNRO); none refuted. SICF, SLG1 and SNRO are
   'unchanged' (a current S/4HANA 2025.001 page, for SLG1 the Fiori Apps Library
   entry, that names the code; the simplification items that print these codes
   use them as tools and set no status for them); SM36 is 'changed' from 'S4TWL -
   JOB SCHEDULING' (choosing Standard Jobs in SM36 was replaced by the Technical
   Job Repository); SNOTE is 'changed' from the What's New entry 'Note Assistant'
   (SAP S/4HANA 2021, Type: Changed); SM37 carries the authored status
   verification_required; SM01 and SM31 carry no status (no official record that
   was checked rules on them). Seven taken from verdict.fixedRecord; SLG1 written
   from the draft (the audit listed no problem). Each status source is a shared
   const (the record's own row). Writer corrections: the empty SM31 alias list
   and the SNRO 'successor: null' dropped; 'only' wording that describes what a
   source means removed (SICF and SNOTE status.he; the SM31, SM36 and SNOTE
   item-row claims; the SM31, SM36 and SNOTE notes); the SM36 notes name 'S4TWL -
   JOB SCHEDULING' instead of its bare numbers (HOUSE-RULES §3.5); Old → New lines
   added (SM01, SM31, SNRO); the rows of the generated records that the audited
   records left out carried over verbatim as context rows with their 2026-09-24
   access date (SICF 2, SM36 6, SM37 3, SNOTE 3, SNRO 5; item rows with the 'not
   yet read' frame sentence replaced), and the SM36 and SM37 notes sentences
   about those rows reworded to match; the SM31 'item 6.0' row, a fragment of
   the BRIM item, is not carried (named in its notes). The generated records for
   the eight ids in transactions-auto.ts are superseded.
   Batch 4 (research and adversarial audit 2026-09-28, written 2026-09-28, access
   date stamped 2026-09-25): 8 audited records for SAP Business Workflow codes
   and the BAPI Explorer (SWEL, SWI1, SWI5, SWIA, SWU2, SWU3, SWUD, BAPI); none
   refuted. SWEL, SWI5, SWIA, SWU2, SWU3 and SWUD are 'changed' and SWI1 is
   'simplified', each from 'ABAPTWL - Change of authorization checks SAP
   Business Workflow' (from SAP_BASIS 756 the S_PROGRAM check of the listed
   workflow transactions and reports is replaced by a check on S_WF_ADM; the
   item names no removal and no successor); SWU3 also cites 'ABAPTWL - Change of
   workflow system user and workflow system jobs'. BAPI is 'unchanged' from the
   2025.001 page 'BAPIs for the Transaction Manager' (Treasury and Risk
   Management); the simplification items that print 'BAPI' use it for the
   interface technique or a function module name. All eight taken from
   verdict.fixedRecord; each status source is a shared const (the record's own
   row). Writer corrections: in the SWIA status.he the 'only' wording removed
   (HOUSE-RULES §3.2), the clause saying S_WF_ADM enables a display/change
   separation dropped (the SWEL audit ruled that the item does not say so) and
   'identical in 2023 FPS03 and 2025 FPS01' reworded to where the item appears
   (the SWI1 audit ruled that the two texts match in substance); the 'only' in
   the SWIA notes removed; the SWI1 and SWU3 notes name the items instead of
   their bare numbers (HOUSE-RULES §3.5); an Old → New line added to SWEL; the
   rows of the generated records that the audited records left out carried over
   verbatim as context rows with their 2026-09-24 access date (SWEL 1, SWI1 2,
   SWU2 1, SWUD 1; in the two 2023 FPS03 item rows the 'not yet read' frame
   sentence replaced; the SWU3 and BAPI fixedRecords already carried theirs),
   and the SWEL, SWI1, SWU2 and SWUD notes reworded to match. The generated
   records for the eight ids in transactions-auto.ts are superseded. */
import type { Evidence, VerificationRecord } from "@/lib/evidence/types";

