    notes: "המחקר קרא את גוף פריט 10.1.57 במלואו (scratchpad/official/SIMPL_OP2025.pdf.txt, שורות 50513-50554) ומצא ש-CJV6 מוזכרת ברשימת שבע הטרנזקציות (CJV1-CJV7) שהפריט מגדיר כחלק מהיקף הקבע (perpetual scope) לאחר שיפור, לא כטרנזקציה שהוחלפה או הוסרה. הבדל שם בין המקורות: ספריית Fiori ורשומת המאגר מציגות את CJV6 כ-Display Administration Data (הצגת נתוני ניהול), והפריט מציג CJV6 Maintenance: Version administration. חיפושים שבוצעו: 'Project Schedule for Versions' (עומק help.sap.com, 21 תוצאות, אותרה אפליקציית Fiori); 'CJV6 Maintenance Version' (21 תוצאות, לא אותר מקור רשמי נוסף ספציפי ל-CJV6 מעבר לפריט הפישוט ולרשומת CJV6 בספריית Fiori). בדיקת fal-app F5611 @S32OP: אפליקציה Project Schedule (SAPUI5), leading GUI transaction ריק, ללא predecessor/successor רשום, כך שאין בסיס רשמי לקבוע successor. CJV7 מופיעה בפריט אך אינה ביקום ה-route manifest, ולכן לא נכללה ב-xrefs. עמדת ECC (SAP ERP) לא עלתה בחיפושים כמקור רשמי נפרד; היא נותרת לא מאומתת, והבסיס היחיד לה הוא סעיף ה-Symptom של הפריט, העוסק בהמרה מ-SAP ERP ל-SAP S/4HANA. הפעולה שסוגרת בפועל: SE93 במערכת היעד לאימות קיום הטרנזקציה, התוכנית והמסך. Old → New: רשומה זו מחליפה את הרשומה הדטרמיניסטית ל-tx:CJV6 ב-transactions-auto.ts (scripts/qa/gen-tx-evidence.mts, 2026-09-24; ישן: ללא הכרעת מעמד, ופריט 'S4TWL - Current simulation functions in project system' הובא בה כהקשר שטרם נקרא; חדש: 'changed' לפי הפריט). שלוש שורות הרשומה הקודמת (רשומת המאגר, ספריית Fiori והפריט) נכללות ברשומה זו. לא בוצעה בדיקה במערכת SAP חיה.",
